"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[7657],{73925:e=>{e.exports=JSON.parse('{"functions":[],"properties":[],"types":[],"name":"TrainFuelGuiController","desc":"Drives the authored `TrainFuelGui` HUD without issuing any network packets.\\nOn every `RenderStepped` frame it asks `TrainStateCache` for the extrapolated\\nfuel level and eases the displayed bar toward it with frame-rate-independent\\nexponential smoothing, so refuel jumps animate smoothly. The bar colour\\nreflects running, braked, or stalled state.\\n\\nThis controller holds no fallback snapshot. It previously seeded one from\\n`TrainConfig` plus `workspace:GetServerTimeNow()` read at module load \u2014\\nbefore the client\'s clock estimate had converged \u2014 which extrapolated to a\\nclamped 0% and disagreed with the diegetic monitor. While the server has not\\nyet sent a snapshot the HUD shows a placeholder instead of a guess.","realm":["Client"],"source":{"line":19,"path":"src/StarterPlayer/StarterPlayerScripts/TrainFuelGuiController.client.luau"}}')}}]);